import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { getSaved } from '../services/api';
import PropertyCard from '../components/PropertyCard';
import EnquiryModal from '../components/EnquiryModal';
import styles from './SavedPage.module.css';

export default function SavedPage() {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [properties, setProperties] = useState([]);
  const [loading,    setLoading]    = useState(true);
  const [enquiryProp, setEnquiryProp] = useState(null);

  useEffect(() => {
    if (!user) { navigate('/login'); return; }
    getSaved()
      .then(({ data }) => setProperties(data.properties || []))
      .catch(() => {})
      .finally(() => setLoading(false));
  }, [user, navigate]);

  return (
    <div className={`container ${styles.wrap}`}>
      <h1 className={styles.heading}>Saved Properties</h1>
      {loading ? (
        <div className={styles.loading}>Loading…</div>
      ) : properties.length === 0 ? (
        <div className={styles.empty}>
          <div style={{ fontSize: 48 }}>❤️</div>
          <div className={styles.emptyTitle}>No saved properties yet</div>
          <div className={styles.emptySub}>Tap the heart icon on any property to save it here.</div>
          <button className={styles.browseBtn} onClick={() => navigate('/search')}>Browse Properties</button>
        </div>
      ) : (
        <div className={styles.grid}>
          {properties.map(p => (
            <PropertyCard key={p.id || p._id} property={p} onEnquire={setEnquiryProp} />
          ))}
        </div>
      )}
      {enquiryProp && <EnquiryModal property={enquiryProp} onClose={() => setEnquiryProp(null)} />}
    </div>
  );
}
